# 3. __call__ and a context manager
class Timer:
    def __enter__(self):
        print("start"); return self
    def __exit__(self, exc_type, exc, tb):
        print("stop"); return False

class Adder:
    def __init__(self, n): self.n = n
    def __call__(self, x): return x + self.n

with Timer():
    print(Adder(5)(10))
